static Hl2Result hl2_results[6], hl2_pending[6];
static TwoWire* hl2_wire = nullptr;
static HardwareSerial* hl2_serial = nullptr;
static uint8_t hl2_rx[48], hl2_cmd = 0, hl2_len = 0, hl2_sum = 0;
static uint16_t hl2_index = 0;
static uint8_t hl2_count = 0, hl2_saved = 0, hl2_algo = 0, hl2_learned = 0, hl2_command = 0;
static int16_t hl2_detected = 0, hl2_total = 0, hl2_remaining = 0, hl2_maxid = 0;
static uint32_t hl2_started = 0, hl2_sent = 0;
