inline int16_t hl2_i16(const uint8_t* data) {
    return int16_t(uint16_t(data[0]) | (uint16_t(data[1]) << 8));
}
inline bool hl2_send(uint8_t command, uint8_t algo, const uint8_t* data, uint8_t length) {
    if (length > 40) return false;
    uint8_t frame[46];
    frame[0] = 0x55; frame[1] = 0xAA; frame[2] = command; frame[3] = algo; frame[4] = length;
    for (uint8_t i = 0; i < length; i++) frame[5 + i] = data[i];
    uint8_t sum = 0;
    for (uint8_t i = 0; i < length + 5; i++) sum += frame[i];
    frame[length + 5] = sum;
    uint8_t size = length + 6;
    if (hl2_wire) {
        // In pieces of at most 32 bytes: the Wire buffer of UNO and Nano.
        hl2_wire->setClock(100000);
        for (uint8_t start = 0; start < size; start += 32) {
            hl2_wire->beginTransmission(uint8_t(0x50));
            for (uint8_t i = start; i < size && i < start + 32; i++) hl2_wire->write(frame[i]);
            if (hl2_wire->endTransmission() != 0) return false;
        }
        return true;
    }
    if (hl2_serial) {
        for (uint8_t i = 0; i < size; i++) if (hl2_serial->write(frame[i]) != 1) return false;
        return true;
    }
    return false;
}
// Copies a length-prefixed text of the frame (name or content) if it was kept in hl2_rx.
inline uint16_t hl2_text(uint16_t at, char* target, uint8_t room) {
    target[0] = 0;
    if (at >= hl2_len || at >= sizeof(hl2_rx)) return at;
    uint8_t length = hl2_rx[at], copied = 0;
    for (uint8_t i = 0; i < length && copied + 1 < room; i++) {
        uint16_t index = at + 1 + i;
        if (index >= sizeof(hl2_rx) || index >= hl2_len) break;
        target[copied++] = char(hl2_rx[index]);
    }
    target[copied] = 0;
    return at + 1 + length;
}
inline void hl2_accept() {
    if (hl2_cmd == 0x1A && hl2_command != 0x01) {
