        else hl2_index = value == 0x55 ? 1 : 0;
        return;
    }
    if (hl2_index == 2) { hl2_cmd = value; hl2_sum += value; hl2_index = 3; return; }
    if (hl2_index == 3) { hl2_sum += value; hl2_index = 4; return; }
    if (hl2_index == 4) { hl2_len = value; hl2_sum += value; hl2_index = 5; return; }
