        for (uint8_t i = 0; i < received && hl2_wire->available(); i++) {
            int value = hl2_wire->read(); if (value < 0) break; hl2_byte(uint8_t(value));
        }
    } else if (hl2_serial) {
        for (uint8_t i = 0; i < 64 && hl2_serial->available(); i++) {
            int value = hl2_serial->read(); if (value < 0) break; hl2_byte(uint8_t(value));
        }
    }
