inline void hl2_reset() {
    hl2_ready = false; hl2_count = 0; hl2_detected = 0; hl2_busy = true; hl2_command = 0x00;
    hl2_started = millis(); hl2_sent = millis() - 200; hl2_index = 0; hl2_done = false; hl2_ok = false;
}
inline void hl2_i2c(TwoWire& bus, const char* block) {
    if (hl2_busy) { rb_fail(block, "HuskyLens 2 está ocupada: usa un solo proceso para comunicar"); return; }
    hl2_wire = &bus; hl2_serial = nullptr; hl2_reset();
}
inline void hl2_uart(HardwareSerial& serial, const char* block) {
    if (hl2_busy) { rb_fail(block, "HuskyLens 2 está ocupada: usa un solo proceso para comunicar"); return; }
