// Handshake (KNOCK) every 200 ms until the camera answers, for up to 5 s while it boots.
inline bool hl2_start(const char* block) {
    if (rb_failed) return true;
    hl2_poll();
    if (hl2_done && hl2_ok) { hl2_ready = true; hl2_busy = false; return true; }
    if (uint32_t(millis() - hl2_started) >= 5000) {
        rb_fail(block, hl2_wire ? "No responde la HuskyLens 2: elige I2C en Ajustes del sistema → Protocolo" : "No responde la HuskyLens 2: elige UART en Ajustes del sistema → Protocolo");
        hl2_busy = false; return true;
    }
    if (uint32_t(millis() - hl2_sent) >= 200) {
        uint8_t data[10] = {0};
        hl2_index = 0; hl2_done = false; hl2_send(0x00, 0, data, 10); hl2_sent = millis();
    }
    return false;
}
inline bool hl2_available(const char* block) {
    if (!hl2_ready) { rb_fail(block, "Configura la HuskyLens 2 al iniciar y espera a que termine"); return false; }
    return !rb_failed;
}
inline void hl2_request(uint8_t command, uint8_t algo, const uint8_t* data, uint8_t length, const char* block) {
    if (!hl2_available(block)) return;
    if (hl2_busy) { rb_fail(block, "HuskyLens 2 está ocupada: usa un solo proceso para comunicar"); return; }
    hl2_busy = true; hl2_command = command; hl2_index = 0; hl2_done = false; hl2_info = false; hl2_ok = false;
