    }
    return false;
}
inline void hl2_algorithm(const String& algorithm, const char* block) {
    uint8_t data[10] = {0};
    data[0] = uint8_t(atoi(algorithm.c_str()));
    hl2_algo = data[0];
    hl2_request(0x0A, 0, data, 10, block);
}
inline void hl2_update(const char* block) {
    hl2_request(0x01, hl2_algo, nullptr, 0, block);
}
inline uint8_t hl2_kind(const String& kind) {
    return kind[0] == 'a' ? 0x1D : 0x1C;
}
inline bool hl2_integer(float value, uint16_t minimum, uint16_t maximum, const char* block) {
    if (!isfinite(value) || value < minimum || value > maximum || value != floorf(value)) {
        rb_fail(block, "HuskyLens 2: número o ID fuera de rango, debe ser entero"); return false;
    }
    return true;
}
inline float hl2_field(const Hl2Result& result, const String& prop) {
    return prop[0] == '4' ? float(result.id) : float(result.value[prop[0] - '0']);
}
inline int hl2_closest(uint8_t kind) {
    int closest = -1; float distance = 0;
    for (uint8_t i = 0; i < hl2_count; i++) {
        const Hl2Result& result = hl2_results[i];
        if (result.kind != kind) continue;
        float dx = result.value[0] - 320.0f, dy = result.value[1] - 240.0f, squared = dx * dx + dy * dy;
        if (closest < 0 || squared < distance) { closest = i; distance = squared; }
    }
    return closest;
}
inline int hl2_find_id(float id, const char* block) {
    if (!hl2_available(block) || !hl2_integer(id, 0, 255, block)) return -1;
    for (uint8_t i = 0; i < hl2_count; i++)
        if (id == 0 ? hl2_results[i].id > 0 : hl2_results[i].id == uint8_t(id)) return i;
    return -1;
}
inline float hl2_objects(const char* block) {
    return hl2_available(block) ? hl2_detected : 0;
}
inline bool hl2_kind_seen(const String& kind, const char* block) {
    return hl2_available(block) && hl2_closest(hl2_kind(kind)) >= 0;
}
inline float hl2_center(const String& prop, const String& kind, const char* block) {
    if (!hl2_available(block)) return -1;
    int index = hl2_closest(hl2_kind(kind));
    return index < 0 ? -1 : hl2_field(hl2_results[index], prop);
}
inline bool hl2_id_seen(float id, const char* block) {
    return hl2_find_id(id, block) >= 0;
}
inline float hl2_id_prop(float id, const String& prop, const char* block) {
    int index = hl2_find_id(id, block);
    return index < 0 ? -1 : hl2_field(hl2_results[index], prop);
}
inline String hl2_center_text(const String& what, const char* block) {
    if (!hl2_available(block)) return String("");
    int index = hl2_closest(0x1C);
    if (index < 0) return String("");
    return String(what[0] == 'n' ? hl2_results[index].name : hl2_results[index].content);
}
inline String hl2_id_text(float id, const String& what, const char* block) {
    int index = hl2_find_id(id, block);
    if (index < 0) return String("");
    return String(what[0] == 'n' ? hl2_results[index].name : hl2_results[index].content);
}
inline float hl2_learned_count(const char* block) {
    return hl2_available(block) ? hl2_maxid : 0;
}
inline float hl2_last_learned(const char* block) {
    return hl2_available(block) ? hl2_learned : 0;
}

