// HUSKYLENS 2 (DFRobot SEN0638): frames 55 AA CMD ALGO LEN DATA SUM; no external camera library.
struct Hl2Result { int16_t value[4]; uint8_t id; uint8_t kind; char name[13]; char content[25]; };
static Hl2Result hl2_results[6], hl2_pending[6];
static TwoWire* hl2_wire = nullptr;
static HardwareSerial* hl2_serial = nullptr;
static uint8_t hl2_rx[48], hl2_cmd = 0, hl2_len = 0, hl2_sum = 0;
static uint16_t hl2_index = 0;
static uint8_t hl2_count = 0, hl2_saved = 0, hl2_algo = 0, hl2_learned = 0, hl2_command = 0;
static int16_t hl2_detected = 0, hl2_total = 0, hl2_remaining = 0, hl2_maxid = 0;
static uint32_t hl2_started = 0, hl2_sent = 0;
static bool hl2_ready = false, hl2_busy = false, hl2_info = false, hl2_done = false, hl2_ok = false;
inline int16_t hl2_i16(const uint8_t* data) {
    return int16_t(uint16_t(data[0]) | (uint16_t(data[1]) << 8));
}
inline bool hl2_send(uint8_t command, uint8_t algo, const uint8_t* data, uint8_t length) {
    if (length > 40) return false;
    uint8_t frame[46];
    frame[0] = 0x55; frame[1] = 0xAA; frame[2] = command; frame[3] = algo; frame[4] = length;
    for (uint8_t i = 0; i < length; i++) frame[5 + i] = data[i];
    uint8_t sum = 0;
    for (uint8_t i = 0; i < length + 5; i++) sum += frame[i];
    frame[length + 5] = sum;
    uint8_t size = length + 6;
    if (hl2_wire) {
        // In pieces of at most 32 bytes: the Wire buffer of UNO and Nano.
        hl2_wire->setClock(100000);
        for (uint8_t start = 0; start < size; start += 32) {
            hl2_wire->beginTransmission(uint8_t(0x50));
            for (uint8_t i = start; i < size && i < start + 32; i++) hl2_wire->write(frame[i]);
            if (hl2_wire->endTransmission() != 0) return false;
        }
        return true;
    }
    if (hl2_serial) {
        for (uint8_t i = 0; i < size; i++) if (hl2_serial->write(frame[i]) != 1) return false;
        return true;
    }
    return false;
}
// Copies a length-prefixed text of the frame (name or content) if it was kept in hl2_rx.
inline uint16_t hl2_text(uint16_t at, char* target, uint8_t room) {
    target[0] = 0;
    if (at >= hl2_len || at >= sizeof(hl2_rx)) return at;
    uint8_t length = hl2_rx[at], copied = 0;
    for (uint8_t i = 0; i < length && copied + 1 < room; i++) {
        uint16_t index = at + 1 + i;
        if (index >= sizeof(hl2_rx) || index >= hl2_len) break;
        target[copied++] = char(hl2_rx[index]);
    }
    target[copied] = 0;
    return at + 1 + length;
}
inline void hl2_accept() {
    if (hl2_cmd == 0x1A && hl2_command != 0x01) {
        hl2_ok = hl2_len >= 4 && hl2_rx[1] == 0;
        if (hl2_command == 0x22) hl2_learned = hl2_ok ? uint8_t(hl2_i16(hl2_rx + 2)) : 0;
        hl2_done = true;
        return;
    }
    if (hl2_command != 0x01 || hl2_len < 10) return;
    if (hl2_cmd == 0x1B && !hl2_info) {
        hl2_maxid = hl2_rx[0];
        hl2_total = hl2_i16(hl2_rx + 2);
        hl2_remaining = hl2_total < 0 ? 0 : hl2_total;
        hl2_info = true; hl2_saved = 0; hl2_done = hl2_remaining == 0;
        return;
    }
    if ((hl2_cmd == 0x1C || hl2_cmd == 0x1D) && hl2_info && hl2_remaining > 0) {
        if (hl2_saved < 6) {
            Hl2Result& result = hl2_pending[hl2_saved++];
            result.kind = hl2_cmd; result.id = hl2_rx[0];
            for (uint8_t i = 0; i < 4; i++) result.value[i] = hl2_i16(hl2_rx + 2 + 2 * i);
            result.name[0] = 0; result.content[0] = 0;
            if (hl2_cmd == 0x1C && hl2_len > 10) hl2_text(hl2_text(10, result.name, sizeof(result.name)), result.content, sizeof(result.content));
        }
        hl2_done = --hl2_remaining == 0;
    }
}
// Byte by byte: keeps the first 48 data bytes and checks the sum of the whole frame.
inline void hl2_byte(uint8_t value) {
    if (hl2_index == 0) {
        if (value == 0x55) { hl2_sum = value; hl2_index = 1; }
        return;
    }
    if (hl2_index == 1) {
        if (value == 0xAA) { hl2_sum += value; hl2_index = 2; }
        else hl2_index = value == 0x55 ? 1 : 0;
        return;
    }
    if (hl2_index == 2) { hl2_cmd = value; hl2_sum += value; hl2_index = 3; return; }
    if (hl2_index == 3) { hl2_sum += value; hl2_index = 4; return; }
    if (hl2_index == 4) { hl2_len = value; hl2_sum += value; hl2_index = 5; return; }
    uint16_t at = hl2_index - 5;
    if (at < hl2_len) {
        if (at < sizeof(hl2_rx)) hl2_rx[at] = value;
        hl2_sum += value; hl2_index++;
        return;
    }
    hl2_index = 0;
    if (value == hl2_sum) hl2_accept(); // A corrupted frame is dropped; the request has a deadline.
}
inline void hl2_poll() {
    if (hl2_wire) {
        hl2_wire->setClock(100000);
        uint8_t received = hl2_wire->requestFrom(uint8_t(0x50), uint8_t(16));
        for (uint8_t i = 0; i < received && hl2_wire->available(); i++) {
            int value = hl2_wire->read(); if (value < 0) break; hl2_byte(uint8_t(value));
        }
    } else if (hl2_serial) {
        for (uint8_t i = 0; i < 64 && hl2_serial->available(); i++) {
            int value = hl2_serial->read(); if (value < 0) break; hl2_byte(uint8_t(value));
        }
    }
}
inline void hl2_reset() {
    hl2_ready = false; hl2_count = 0; hl2_detected = 0; hl2_busy = true; hl2_command = 0x00;
    hl2_started = millis(); hl2_sent = millis() - 200; hl2_index = 0; hl2_done = false; hl2_ok = false;
}
inline void hl2_i2c(TwoWire& bus, const char* block) {
    if (hl2_busy) { rb_fail(block, "HuskyLens 2 está ocupada: usa un solo proceso para comunicar"); return; }
    hl2_wire = &bus; hl2_serial = nullptr; hl2_reset();
}
inline void hl2_uart(HardwareSerial& serial, const char* block) {
    if (hl2_busy) { rb_fail(block, "HuskyLens 2 está ocupada: usa un solo proceso para comunicar"); return; }
    hl2_wire = nullptr; hl2_serial = &serial; hl2_reset();
}
// Handshake (KNOCK) every 200 ms until the camera answers, for up to 5 s while it boots.
inline bool hl2_start(const char* block) {
    if (rb_failed) return true;
    hl2_poll();
    if (hl2_done && hl2_ok) { hl2_ready = true; hl2_busy = false; return true; }
    if (uint32_t(millis() - hl2_started) >= 5000) {
        rb_fail(block, hl2_wire ? "No responde la HuskyLens 2: elige I2C en Ajustes del sistema → Protocolo" : "No responde la HuskyLens 2: elige UART en Ajustes del sistema → Protocolo");
        hl2_busy = false; return true;
    }
    if (uint32_t(millis() - hl2_sent) >= 200) {
        uint8_t data[10] = {0};
        hl2_index = 0; hl2_done = false; hl2_send(0x00, 0, data, 10); hl2_sent = millis();
    }
    return false;
}
inline bool hl2_available(const char* block) {
    if (!hl2_ready) { rb_fail(block, "Configura la HuskyLens 2 al iniciar y espera a que termine"); return false; }
    return !rb_failed;
}
inline void hl2_request(uint8_t command, uint8_t algo, const uint8_t* data, uint8_t length, const char* block) {
    if (!hl2_available(block)) return;
    if (hl2_busy) { rb_fail(block, "HuskyLens 2 está ocupada: usa un solo proceso para comunicar"); return; }
    hl2_busy = true; hl2_command = command; hl2_index = 0; hl2_done = false; hl2_info = false; hl2_ok = false;
    hl2_started = millis();
    if (!hl2_send(command, algo, data, length)) { hl2_busy = false; rb_fail(block, "No se pudo enviar la trama a la HuskyLens 2"); }
}
inline bool hl2_wait(const char* block) {
    if (rb_failed) return true;
    hl2_poll();
    if (hl2_done) {
        hl2_busy = false;
        if (hl2_command == 0x01) {
            for (uint8_t i = 0; i < hl2_saved; i++) hl2_results[i] = hl2_pending[i];
            hl2_count = hl2_saved; hl2_detected = hl2_total;
        } else {
            // Changing the algorithm or what it learned invalidates the cached results.
            hl2_count = 0; hl2_detected = 0;
            if (hl2_command == 0x0A && !hl2_ok) rb_fail(block, "La HuskyLens 2 no pudo cambiar de algoritmo");
        }
        return true;
    }
    uint32_t timeout = hl2_command == 0x01 ? 500 : hl2_command == 0x0A ? 5000 : 2000;
    if (uint32_t(millis() - hl2_started) >= timeout) {
        hl2_busy = false; rb_fail(block, "No responde la HuskyLens 2: trama incompleta o checksum inválido"); return true;
    }
    return false;
}
inline void hl2_algorithm(const String& algorithm, const char* block) {
    uint8_t data[10] = {0};
    data[0] = uint8_t(atoi(algorithm.c_str()));
    hl2_algo = data[0];
    hl2_request(0x0A, 0, data, 10, block);
}
inline void hl2_update(const char* block) {
    hl2_request(0x01, hl2_algo, nullptr, 0, block);
}
inline uint8_t hl2_kind(const String& kind) {
    return kind[0] == 'a' ? 0x1D : 0x1C;
}
inline bool hl2_integer(float value, uint16_t minimum, uint16_t maximum, const char* block) {
    if (!isfinite(value) || value < minimum || value > maximum || value != floorf(value)) {
        rb_fail(block, "HuskyLens 2: número o ID fuera de rango, debe ser entero"); return false;
    }
    return true;
}
inline float hl2_field(const Hl2Result& result, const String& prop) {
    return prop[0] == '4' ? float(result.id) : float(result.value[prop[0] - '0']);
}
inline int hl2_closest(uint8_t kind) {
    int closest = -1; float distance = 0;
    for (uint8_t i = 0; i < hl2_count; i++) {
        const Hl2Result& result = hl2_results[i];
        if (result.kind != kind) continue;
        float dx = result.value[0] - 320.0f, dy = result.value[1] - 240.0f, squared = dx * dx + dy * dy;
        if (closest < 0 || squared < distance) { closest = i; distance = squared; }
    }
    return closest;
}
inline int hl2_find_id(float id, const char* block) {
    if (!hl2_available(block) || !hl2_integer(id, 0, 255, block)) return -1;
    for (uint8_t i = 0; i < hl2_count; i++)
        if (id == 0 ? hl2_results[i].id > 0 : hl2_results[i].id == uint8_t(id)) return i;
    return -1;
}
inline float hl2_objects(const char* block) {
    return hl2_available(block) ? hl2_detected : 0;
}
inline bool hl2_kind_seen(const String& kind, const char* block) {
    return hl2_available(block) && hl2_closest(hl2_kind(kind)) >= 0;
}
inline float hl2_center(const String& prop, const String& kind, const char* block) {
    if (!hl2_available(block)) return -1;
    int index = hl2_closest(hl2_kind(kind));
    return index < 0 ? -1 : hl2_field(hl2_results[index], prop);
}
inline bool hl2_id_seen(float id, const char* block) {
    return hl2_find_id(id, block) >= 0;
}
inline float hl2_id_prop(float id, const String& prop, const char* block) {
    int index = hl2_find_id(id, block);
    return index < 0 ? -1 : hl2_field(hl2_results[index], prop);
}
inline String hl2_center_text(const String& what, const char* block) {
    if (!hl2_available(block)) return String("");
    int index = hl2_closest(0x1C);
    if (index < 0) return String("");
    return String(what[0] == 'n' ? hl2_results[index].name : hl2_results[index].content);
}
inline String hl2_id_text(float id, const String& what, const char* block) {
    int index = hl2_find_id(id, block);
    if (index < 0) return String("");
    return String(what[0] == 'n' ? hl2_results[index].name : hl2_results[index].content);
}
inline float hl2_learned_count(const char* block) {
    return hl2_available(block) ? hl2_maxid : 0;
}
inline float hl2_last_learned(const char* block) {
    return hl2_available(block) ? hl2_learned : 0;
